// of returns the logo path of a Plugin kind, or "".
function of(kind) {
    const slug = kinds[kind];
    return slug ? paths[slug] : "";
}

// Full-color logos, drawn as pictures instead of one-color paths. A plugin
// the owner added (mcp-…) takes one when its kind names the brand.
var images = {
    "pluggy": "pluggy",
    "google": "google",
    "produtos": "google",
    "aliexpress": "aliexpress",
    "mercadolivre": "mercadolivre",
    "polymarket": "polymarket",
    "pix": "pix"
};

// Each app of a connector that has several (Google), by the app's name.
var appImages = {
    "google": {
        "gmail": "google-gmail",
        "drive": "google-drive",
        "agenda": "google-calendar",
        "planilhas": "google-sheets",
        "tarefas": "google-tasks",
        "contatos": "google-contacts",
        "youtube": "google-youtube"
    }
};

// image returns the URL of a Plugin kind's full-color logo, or "". With
// app (an app's name, like "Gmail"), that app's own logo when it has one.
function image(kind, app) {
    const apps = appImages[kind || ""];
    const own = apps && app ? apps[String(app).toLowerCase()] : "";
    if (own)
        return "qrc:/qt/qml/Avora/resources/logos/" + own + ".png";
    let file = images[kind || ""];
    if (!file && String(kind || "").startsWith("mcp-")) {
        for (const k in images)
            if (kind.indexOf(k) >= 0) { file = images[k]; break; }
    }
    return file ? "qrc:/qt/qml/Avora/resources/logos/" + file + ".png" : "";
}

// color returns the brand color of a Plugin kind, or "".
function color(kind) {
    return colors[kind] || "";
}
